// symbol table: varName -> type (e.g. "int", "float")
Map<String, String> symbolTable = new HashMap<String,String>();
// var values (numeric): varName -> Number value (if initialized)
Map<String, Number> varValues = new HashMap<String,Number>();

// helper to format an argument for printing in funcall
private String formatArg(Object arg) {
    if (arg == null) return "null";
    if (arg instanceof ArithmeticResult) {
        ArithmeticResult ar = (ArithmeticResult) arg;
        if (ar.varName != null) {
            String type = symbolTable.get(ar.varName);
            if (type == null) type = "unknown";
            return type + " " + ar.varName;
        } else if (ar.value != null) {
            return ar.value.toString();
        } else {
            return (ar.operation != null) ? ar.operation : "expr";
        }
    } else if (arg instanceof String) {
        String name = (String) arg;
        String type = symbolTable.get(name);
        if (type == null) type = "unknown";
        return type + " " + name;
    } else {
        return arg.toString();
    }
}


private Number addNumbers(Number a, Number b) {
    if (a instanceof Double || b instanceof Double) {
        return Double.valueOf(a.doubleValue() + b.doubleValue());
    } else if (a instanceof Float || b instanceof Float) {
        return Float.valueOf(a.floatValue() + b.floatValue());
    } else if (a instanceof Long || b instanceof Long) {
        return Long.valueOf(a.longValue() + b.longValue());
    } else {
        return Integer.valueOf(a.intValue() + b.intValue());
    }
}

private Number subNumbers(Number a, Number b) {
    if (a instanceof Double || b instanceof Double) {
        return Double.valueOf(a.doubleValue() - b.doubleValue());
    } else if (a instanceof Float || b instanceof Float) {
        return Float.valueOf(a.floatValue() - b.floatValue());
    } else if (a instanceof Long || b instanceof Long) {
        return Long.valueOf(a.longValue() - b.longValue());
    } else {
        return Integer.valueOf(a.intValue() - b.intValue());
    }
}

private Number mulNumbers(Number a, Number b) {
    if (a instanceof Double || b instanceof Double) {
        return Double.valueOf(a.doubleValue() * b.doubleValue());
    } else if (a instanceof Float || b instanceof Float) {
        return Float.valueOf(a.floatValue() * b.floatValue());
    } else if (a instanceof Long || b instanceof Long) {
        return Long.valueOf(a.longValue() * b.longValue());
    } else {
        return Integer.valueOf(a.intValue() * b.intValue());
    }
}

private Number divNumbers(Number a, Number b) {
    if (a.doubleValue() == 0.0) {
        throw new ArithmeticException("Division by zero");
    }
    if (a instanceof Double || b instanceof Double) {
        return Double.valueOf(a.doubleValue() / b.doubleValue());
    } else if (a instanceof Float || b instanceof Float) {
        return Float.valueOf(a.floatValue() / b.floatValue());
    } else if (a instanceof Long || b instanceof Long) {
        return Long.valueOf(a.longValue() / b.longValue());
    } else {
        return Integer.valueOf(a.intValue() / b.intValue());
    }
}

private Number modNumbers(Number a, Number b) {
    if (a instanceof Double || b instanceof Double) {
        return Double.valueOf(a.doubleValue() % b.doubleValue());
    } else if (a instanceof Float || b instanceof Float) {
        return Float.valueOf(a.floatValue() % b.floatValue());
    } else if (a instanceof Long || b instanceof Long) {
        return Long.valueOf(a.longValue() % b.longValue());
    } else {
        return Integer.valueOf(a.intValue() % b.intValue());
    }
}


  public void report_error(String message, Object info) {
    StringBuilder m = new StringBuilder("Error ");

    if (info instanceof java_cup.runtime.Symbol)
      m.append( "("+info.toString()+")" );

    m.append(" : "+message);

    System.out.println(m);
  }

  public void report_fatal_error(String message, Object info) {
    report_error(message, info);
    throw new RuntimeException("Fatal Syntax Error");
  }
