class ArithmeticResult {
    Number value;
    String operation;
    boolean detailed;
    String varName; // اگر این نتیجه مربوط به یک IDENTIFIER باشد، نام متغیر اینجاست

    public ArithmeticResult(Number value, String operation, boolean detailed) {
        this.value = value;
        this.operation = operation;
        this.detailed = detailed;
        this.varName = null;
    }

    public ArithmeticResult(Number value, String operation, boolean detailed, String varName) {
        this.value = value;
        this.operation = operation;
        this.detailed = detailed;
        this.varName = varName;
    }

    public boolean isVariable() { return varName != null; }
    public String getVarName() { return varName; }

    @Override
    public String toString() {
        if (detailed) {
            return "Expression: " + operation ;//+ "="+ value ;
        }
        return operation;
    }
}
